<?php
require_once __DIR__ . '/config.php'; require_login(); $pdo=db(); require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));if($name==='')flash('Nama kategori wajib diisi.','error');else try{if($id){$s=$pdo->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$s->execute([$name,$desc?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->execute([$name,$desc?:null]);}flash('Kategori disimpan.');}catch(Throwable $e){flash('Kategori gagal disimpan. Pastikan nama tidak duplikat.','error');}redirect('categories.php');}
if(isset($_GET['delete'])){try{$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_GET['delete']]);flash('Kategori dihapus.');}catch(Throwable $e){flash('Kategori tidak dapat dihapus.','error');}redirect('categories.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}
$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$pageTitle='Kategori';require 'partials_header.php';?>
<section class="panel"><div class="panel-heading"><h2><?= $edit?'Edit kategori':'Tambah kategori' ?></h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div><label>Nama kategori *</label><input name="name" required maxlength="100" value="<?= e($edit['name']??'') ?>"></div><div><label>Deskripsi</label><input name="description" maxlength="255" value="<?= e($edit['description']??'') ?>"></div><div class="wide"><button class="btn primary">Simpan</button> <?php if($edit): ?><a class="btn" href="categories.php">Batal</a><?php endif; ?></div></form></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Deskripsi</th><th>Jumlah produk</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['description']) ?></td><td><?= $r['product_count'] ?></td><td class="actions"><a href="?edit=<?= $r['id'] ?>">Edit</a><a class="danger-link" href="?delete=<?= $r['id'] ?>" onclick="return confirm('Hapus kategori?')">Hapus</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php require 'partials_footer.php'; ?>
